import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterOutlet } from '@angular/router';
import { NavbarComponent } from './components/navbar/navbar.component';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, RouterOutlet, NavbarComponent],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  title = 'Infy_Bank360';
}
<div class="d-flex flex-column min-vh-100 bg-light-subtle">
  <app-navbar></app-navbar>

  <main class="flex-grow-1 py-4">
    <div class="container-xl">
      <router-outlet></router-outlet>
    </div>
  </main>

  <footer class="py-3 bg-white border-top text-center text-muted small mt-auto">
    <div class="container d-flex flex-wrap justify-content-between align-items-center">
      <span>&copy; 2026 <strong>Infy_Bank360</strong>. All rights reserved. Infosys Financial Microservices Architecture.</span>
      <span class="text-secondary">Connected via Spring Cloud Gateway <span class="badge bg-primary-subtle text-primary border border-primary-subtle">localhost:8080</span></span>
    </div>
  </footer>
</div>
